report=$(printf '%s\n' "$OUT" | grep -Eo '/[^[:space:]]*/architecture-review-[^[:space:]]*\.html' | tail -1); python3 - "$report" <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys

REQUIRED_EVIDENCE = {
    "module-callers",
    "caller-interface-knowledge",
    "locality-leverage",
    "deletion-test",
    "dependency-adapters",
    "tests-interface-surface",
    "context-decision-conflict",
}
REQUIRED_DIAGRAMS = {"before", "after"}
VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}

class ReportParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
        self.candidates_section_level = None
        self.candidates_sections = 0
        self.candidate_articles = 0
        self.candidate = None
        self.candidate_level = None
        self.candidates = []
        self.surfaces = []
        self.no_candidate_level = None
        self.no_candidate_markers = []
        self.no_candidate_text = []
        self.top_level = None
        self.top_sections = 0
        self.top_links = []

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        level = len(self.stack) + 1
        if tag == "section" and attributes.get("id") == "candidates":
            self.candidates_sections += 1
            if self.candidates_sections != 1:
                self.errors.append("duplicate candidates section")
            self.candidates_section_level = level
        in_candidates = self.candidates_section_level is not None
        if tag == "article" and not in_candidates:
            self.errors.append("article outside candidates section")
        if in_candidates and tag == "article":
            self.candidate_articles += 1
            if self.candidate is not None:
                self.errors.append("nested candidate article")
            if "data-architecture-candidate" not in attributes:
                self.errors.append("unmarked candidate article")
            self.candidate = {"id": attributes.get("id", ""), "evidence": {}, "diagrams": {}}
            self.candidate_level = level
        if self.candidate is not None:
            if "data-evidence" in attributes:
                name = attributes["data-evidence"]
                self.candidate["evidence"].setdefault(name, []).append([])
                self.surfaces.append((level, self.candidate["evidence"][name][-1]))
            if "data-diagram-text" in attributes:
                name = attributes["data-diagram-text"]
                self.candidate["diagrams"].setdefault(name, []).append([])
                self.surfaces.append((level, self.candidate["diagrams"][name][-1]))
        if attributes.get("id") == "no-candidates":
            if not in_candidates:
                self.errors.append("zero-state marker outside candidates section")
            self.no_candidate_level = level
            self.no_candidate_markers.append(attributes.get("data-candidate-count"))
            self.no_candidate_text.append([])
        if tag == "section" and attributes.get("id") == "top-recommendation":
            self.top_sections += 1
            self.top_level = level
        if self.top_level is not None and tag == "a":
            self.top_links.append(attributes.get("href", ""))
        if tag not in VOID_TAGS:
            self.stack.append(tag)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in VOID_TAGS:
            self.handle_endtag(tag)

    def handle_data(self, data):
        for _level, chunks in self.surfaces:
            chunks.append(data)
        if self.no_candidate_level is not None:
            self.no_candidate_text[-1].append(data)

    def handle_endtag(self, tag):
        if not self.stack or self.stack[-1] != tag:
            self.errors.append(f"mismatched closing tag: {tag}")
            return
        level = len(self.stack)
        self.surfaces = [(surface_level, chunks) for surface_level, chunks in self.surfaces if surface_level != level]
        if self.candidate_level == level and tag == "article":
            self.candidates.append(self.candidate)
            self.candidate = None
            self.candidate_level = None
        if self.no_candidate_level == level:
            self.no_candidate_level = None
        if self.top_level == level and tag == "section":
            self.top_level = None
        if self.candidates_section_level == level and tag == "section":
            self.candidates_section_level = None
        self.stack.pop()

parser = ReportParser()
parser.feed(Path(sys.argv[1]).read_text(encoding="utf-8"))
parser.close()
if parser.stack:
    parser.errors.append("unclosed tags")
if parser.candidate is not None:
    parser.errors.append("unclosed candidate article")
if parser.candidates_section_level is not None:
    parser.errors.append("unclosed candidates section")

candidate_count = len(parser.candidates)
if parser.candidates_sections != 1:
    parser.errors.append("report requires exactly one candidates section")
if candidate_count != parser.candidate_articles:
    parser.errors.append("every candidate article must be marked and closed")
if candidate_count == 0:
    zero_text = " ".join(" ".join("".join(chunks).split()) for chunks in parser.no_candidate_text)
    if parser.no_candidate_markers != ["0"] or "No evidence-backed candidates." not in zero_text:
        parser.errors.append("zero candidates require the explicit zero-state marker")
    if parser.top_sections != 0:
        parser.errors.append("zero candidates must omit top recommendation")
elif 1 <= candidate_count <= 5:
    if parser.no_candidate_markers:
        parser.errors.append("positive reports must omit the zero-state marker")
    candidate_ids = [candidate["id"] for candidate in parser.candidates]
    if any(not candidate_id for candidate_id in candidate_ids) or len(set(candidate_ids)) != candidate_count:
        parser.errors.append("candidate IDs must be non-empty and unique")
    for candidate in parser.candidates:
        evidence = candidate["evidence"]
        diagrams = candidate["diagrams"]
        if set(evidence) != REQUIRED_EVIDENCE or any(len(values) != 1 or not "".join(values[0]).strip() for values in evidence.values()):
            parser.errors.append(f"candidate {candidate['id']} lacks one complete evidence surface")
        if set(diagrams) != REQUIRED_DIAGRAMS or any(len(values) != 1 or not "".join(values[0]).strip() for values in diagrams.values()):
            parser.errors.append(f"candidate {candidate['id']} lacks before/after diagram text")
    if parser.top_sections != 1 or len(parser.top_links) != 1 or parser.top_links[0] not in {f"#{candidate_id}" for candidate_id in candidate_ids}:
        parser.errors.append("top recommendation must link exactly once to a candidate")
else:
    parser.errors.append("candidate count must be zero or one to five")

if parser.errors:
    raise SystemExit("; ".join(parser.errors))
PY
